draw:
var k = 8.99e9;
var R = p.R / 100.0;
var Q = p.Q * 1e-9;
var rp = p.r / 100.0;
var rmax = 0.25;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function Efield(r) {
  if (r <= 0) return 0;
  if (r < R) return k * Q * r / (R * R * R);
  return k * Q / (r * r);
}
var Epeak = k * Q / (R * R);
var Enow = Efield(rp);
var Qenc = rp < R ? Q * Math.pow(rp / R, 3) : Q;

// ---- left panel: cross section
var cx = W * 0.2, cy = H * 0.5;
var scale = Math.min(W * 0.17, H * 0.42) / rmax;
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.beginPath(); ctx.arc(cx, cy, R * scale, 0, Math.PI * 2); ctx.fill();
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cx, cy, R * scale, 0, Math.PI * 2); ctx.stroke();
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.arc(cx, cy, rp * scale, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("Gaussian sphere", cx, H - 6);
ctx.textAlign = "left";

// ---- right panel: E versus r
var x0 = W * 0.42, x1 = W - 16, y0 = H - 30, y1 = 18;
var gw = x1 - x0, gh = y0 - y1;
var Emax = Math.max(Epeak * 1.15, 1);
var GX = function (r) { return x0 + r / rmax * gw; };
var GY = function (e) { return y0 - Math.min(e, Emax) / Emax * gh; };

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, y1); ctx.lineTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(GX(R), y0); ctx.lineTo(GX(R), y1); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 220; i++) {
  var r = rmax * i / 220;
  var X = GX(r), Y = GY(Efield(r));
  i === 0 ? ctx.moveTo(X, Y) : ctx.lineTo(X, Y);
}
ctx.stroke();

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(GX(rp), GY(Enow), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("E (N/C)", x0 + 4, y1 + 4);
ctx.fillText("r (cm)", x1 - 36, y0 + 16);
ctx.fillText("0", x0 - 4, y0 + 16);
ctx.fillText("r = R", GX(R) + 4, y1 + 16);
ctx.fillText("25", x1 - 10, y0 + 16);

out.note = "r = " + p.r.toFixed(1) + " cm, enclosed charge " + (Qenc * 1e9).toFixed(2) +
  " nC, E = " + Enow.toFixed(0) + " N/C (surface value " + Epeak.toFixed(0) + " N/C)";
